This tool compares album artwork across artists by calculating similarity scores from image feature embeddings. Selecting an album reveals which cover in the collection shares the closest visual aesthetic and which is the most visually distinct.


Hover over points to see individual track titles and tempo across artists.






This scatter plot maps individual songs by their danceability and energy levels across all five artists. It illustrates how different artists occupy distinct sonic spaces, from high-energy dance tracks to slower acoustic ballads.


Hover over any state to see which artist and song lead listening trends.






This choropleth map highlights the most popular artist and top-streamed track across each US state. It reveals clear regional listening patterns, from Bruce Springsteen’s dominance in the Northeast to Kodak Black’s strong following in the South.


Answer three quick questions to discover your artist match and get a recommended album to start exploring.

viewof quizVibe = Inputs.select(
  [
    "Storytelling, acoustic grit & heartland rock",
    "High-energy choreography & global pop",
    "Emotional lyricism & melodic pop hooks",
    "Raw southern trap & bass-heavy street anthems",
    "Theatrical rock harmonies & stadium anthems"
  ],
  { label: "1. What is your go-to vibe?" }
)

viewof quizEra = Inputs.select(
  ["70s Classic Rock", "80s Big Stage", "2010s Pop & Rap", "2020s Streaming Age"],
  { label: "2. Preferred musical era:" }
)

viewof quizMood = Inputs.select(
  ["Deep & contemplative", "Uplifting & danceable", "Bold & confident", "Epic & dramatic"],
  { label: "3. Current listening mood:" }
)

twin = {
  if (quizVibe.includes("global pop") || (quizMood === "Uplifting & danceable" && quizEra.includes("2010s"))) {
    return {
      artist: "BTS",
      album: "Map Of The Soul 7 (2020)",
      song: "Dynamite / ON",
      file: "data/bts_2020_map_of_the_soul_7.jpg",
      desc: "You thrive on vibrant energy, high-production soundscapes, and global pop choreography."
    };
  } else if (quizVibe.includes("heartland") || (quizEra.includes("70s") && quizMood.includes("Deep"))) {
    return {
      artist: "Bruce Springsteen",
      album: "Born To Run (1975)",
      song: "Thunder Road",
      file: "data/bruce_springsteen_1975_born_to_run.jpg",
      desc: "You connect with soulful storytelling, grit, anthemic sax solos, and raw American road poetry."
    };
  } else if (quizVibe.includes("Theatrical") || quizEra.includes("70s") || quizMood.includes("Epic")) {
    return {
      artist: "Queen",
      album: "A Night At The Opera (1975)",
      song: "Bohemian Rhapsody",
      file: "data/queen_1975_a_night_at_the_opera.jpg",
      desc: "You love grandeur, multi-part vocal harmonies, stadium rock, and fearless artistic experimentation."
    };
  } else if (quizVibe.includes("southern trap") || quizMood.includes("Bold")) {
    return {
      artist: "Kodak Black",
      album: "Dying To Live (2018)",
      song: "Super Gremlin",
      file: "data/kodak_black_2018_dying_to_live.jpg",
      desc: "You love heavy southern 808s, raw authenticity, emotional melodies, and distinctive flows."
    };
  } else {
    return {
      artist: "Taylor Swift",
      album: "1989 (2014)",
      song: "Blank Space / Cruel Summer",
      file: "data/taylor_swift_2014_1989.jpg",
      desc: "You appreciate sharp confessional songwriting, relatable narratives, and sparkling pop melody."
    };
  }
}

